SELECT o.store_id, o.customer_id, t.pct_success, t.min_amount FROM orders o JOIN (SELECT order_id, ROUND((100 * SUM(CASE WHEN status = 'SUCCESS' THEN 1 ELSE 0 END)) / COUNT(*), 1) AS pct_success, MIN(amount) AS min_amount FROM payments GROUP BY order_id) t ON o.id = t.order_id ORDER BY o.customer_id, pct_success DESC
